let __v_350 = pyrt::literals::decode("{\"$tuple\":[{\"$tuple\":[{\"$tuple\":[\"polenta\",\"couscous\",\"porridge\",\"oats\",\"oatmeal\",\"semolina\",\"grits\",\"mash\",\"mashed potato\",\"mashed potatoes\",\"potato\",\"potatoes\"]},\"lumpy-starch\"]},{\"$tuple\":[{\"$tuple\":[\"custard\",\"cream\",\"sauce\",\"sauces\",\"gravy\",\"roux\",\"cheese sauce\",\"white sauce\",\"batter\",\"pancakes\",\"pancake\",\"yorkshire\"]},\"lumpy-liquid\"]},{\"$tuple\":[{\"$tuple\":[\"hummus\",\"houmous\",\"humus\",\"dip\",\"dips\",\"pesto\",\"smoothie\"]},\"lumpy-blend\"]}]}")?;
