let __v_2607 = pyrt::literals::decode("{\"$tuple\":[\"how do i\",\"how to\",\"how should i\",\"best way\",\"recipe\",\"recipes\",\"goes with\",\"go with\",\"go nicely\",\"serve with\",\"serving with\",\"side for\",\"sides for\",\"side dish\",\"with what\",\"alongside\",\"to serve\",\"for dinner\",\"for tea\",\"for lunch\",\"for a crowd\",\"for two\",\"for four\",\"what about\",\"how about\",\"what if\",\"same for\",\"favourite\",\"favorite\",\"favourites\",\"favorites\",\"your favourite\",\"your favorite\",\"you like\",\"do you like\",\"would you\",\"prefer\",\"your pick\",\"pick one\",\"which one\",\"what would you\",\"how long\",\"how much\",\"make it\",\"make them\",\"cook it\",\"cook them\",\"should i\",\"can i\",\"calories\",\"good for you\",\"healthy\",\"what is a good\",\"what is the best\",\"best way\",\"for dinner\",\"ideas\",\"suggest\",\"recommend\",\"which is better\",\"casserole dish\",\"hash brown\",\"hash browns\",\"tap\",\"taps\",\"washer\",\"plumbing\",\"pipe\",\"pipes\",\"paint\",\"radiator\",\"boiler\",\"called\",\"named\",\"puppy\",\"puppies\",\"dog\",\"dogs\",\"kitten\",\"kittens\",\"cat\",\"cats\",\"hamster\",\"rabbit\",\"lol\",\"haha\",\"ha\",\"thanks\",\"ta\",\"cheers\",\"bye\",\"gotta\",\"swap\",\"swaps\",\"swap it\",\"ceiling\",\"ceilings\",\"roof\",\"wall\",\"walls\",\"floor\",\"floors\",\"water\",\"damp\",\"fridge\",\"freezer\",\"window\",\"windows\",\"door\",\"doors\",\"tag\",\"tags\",\"hashtag\",\"hashtags\",\"symbol\",\"key\",\"code\",\"sign\",\"taste like\",\"tastes like\",\"smell like\",\"look like\",\"sound like\",\"dance\",\"dances\",\"dancing\",\"dancers\"]}")?;
